import{_ as t,o as r,c as a,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-11-16","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-11-16","date":"2021-11-16T00:00:00.000Z","updated":"2021-11-17T00:00:00.000Z","tags":["Ceph","分布式存储","Orchestrator","集群部署","大规模集群"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-11-16.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-11-16.md","lastUpdated":1780460162000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-11-16.md"};function o(n,l,s,h,u,c){return r(),a("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>会议主题</strong>: Ceph 协调器会议</li><li><strong>日期</strong>: 2021年11月16日</li><li><strong>参会人员</strong>: [参会人员名单]</li><li><strong>主持人</strong>: [主持人姓名]</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Cephalocon 论文征集</strong></p><ul><li>论文征集截止日期为12月10日。</li><li>鼓励团队成员提交关于安全性和NSF ADM文档的演讲提案。</li><li>讨论了为不同开发领域（如FDM、Flu Culture系统）设置专门会议环节的可能性。</li></ul></li><li><p><strong>大型集群部署计划</strong></p><ul><li>计划在澳大利亚珀斯的Poise超级计算中心部署大规模的SF ADM集群。</li><li>讨论了如何有效组织和利用时间，避免部署过程中的浪费。</li><li>提出了使用IRC或Matrix作为通信渠道，确保信息的连续性和可访问性。</li></ul></li><li><p><strong>集群测试和资源利用</strong></p><ul><li>讨论了如何优化集群的测试和资源利用，包括重用现有集群和有效管理NVMe设备。</li><li>确认了Patrick已经对self-FFS进行了研究，并期待其他组件也能利用这一集群。</li></ul></li><li><p><strong>技术细节和改进</strong></p><ul><li>讨论了从runC切换到crun以改善上游生育测试中的组错误问题。</li><li>确认了Sage已经提交了相关的PR，并期待这一改变能带来更稳定的运行环境。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>向Cephalocon组织者提出建议，为不同的开发领域设置专门的会议环节。</li><li>确认使用Matrix作为通信渠道，以替代传统的IRC。</li><li>确认了集群部署和测试的具体计划，包括重用现有集群和优化资源利用。</li><li>确认了技术改进的方向，特别是从runC切换到crun。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>向Cephalocon组织者提出建议，设置专门的会议环节。</li><li>确认并实施使用Matrix作为通信渠道。</li><li>继续推进大型集群的部署和测试工作，确保资源的有效利用。</li><li>实施从runC到crun的技术切换，并更新相关文档。</li></ul><h4 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h4><ul><li><strong>日期</strong>: 下周二</li><li><strong>地点</strong>: [会议链接或地点]</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li><strong>时间</strong>: [具体结束时间]</li><li><strong>备注</strong>: 无其他议题</li></ul><p><strong>会议记录人</strong>: [记录人姓名] <strong>审核人</strong>: [审核人姓名]</p>',14)])])}const p=t(i,[["render",o]]);export{g as __pageData,p as default};
